SCALE_PULSES.c:
unsigned scale_pulses(unsigned pulses, unsigned scale)
{
    return pulses * scale;
}

QUOTIENT_UNSIGNED.c:
unsigned quotient_unsigned(unsigned total, unsigned count)
{
    return total / count;
}

QUOTIENT_SIGNED.c:
int quotient_signed(int total, int count)
{
    return total / count;
}

SCALED_TOTAL.c:
unsigned scaled_total(unsigned pulses, unsigned scale, unsigned total)
{
    return total + pulses * scale;
}

REMAINDER_SIGNED.c:
int remainder_signed(int total, int count)
{
    return total % count;
}

WIDE_SIGNED.c:
long wide_signed(int adjustment, int scale)
{
    return (long)adjustment * scale;
}

WIDE_UNSIGNED.c:
unsigned long wide_unsigned(unsigned pulses, unsigned scale)
{
    return (unsigned long)pulses * scale;
}
